61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
65	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
66	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
67	     */
68	    private static final Pattern EMAIL_PATTERN =
69	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    /**
105	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
106	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
107	     */
108	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
109	        List<String> missing = new ArrayList<>();
110	        if (isBlank(ownerFieldsDto.getFirstName())) {
111	            missing.add("firstName");
112	        }
113	        if (isBlank(ownerFieldsDto.getLastName())) {
114	            missing.add("lastName");
115	        }
116	        if (isBlank(ownerFieldsDto.getAddress())) {
117	            missing.add("address");
118	        }
119	        if (isBlank(ownerFieldsDto.getCity())) {
120	            missing.add("city");
121	        }
122	        if (isBlank(ownerFieldsDto.getTelephone())) {
123	            missing.add("telephone");
124	        }
125	        if (!missing.isEmpty()) {
126	            throw new RequiredFieldsMissingException(missing);
127	        }
128	    }
129	
130	    private static boolean isBlank(String value) {
131	        return value == null || value.isBlank();
132	    }
133	
134	    /**
135	     * Normalizes a telephone on create by removing every non-digit character and requiring the
136	     * result to be exactly 10 digits. Returns the 10-digit value to be stored and returned.
137	     *
138	     * @param telephone the raw telephone as supplied by the caller
139	     * @return the normalized 10-digit telephone
140	     * @throws InvalidTelephoneException if the stripped value is not exactly 10 digits
141	     */
142	    private static String normalizeTelephone(String telephone) {
143	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
144	        if (digits.length() != 10) {
145	            throw new InvalidTelephoneException(
146	                "Telephone must contain exactly 10 digits after removing non-digit characters");
147	        }
148	        return digits;
149	    }
150	
151	    /**
152	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
153	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
154	     *
155	     * @param email the raw email as supplied by the caller, may be {@code null}
156	     * @return the lower-cased email, or {@code null} when none was supplied
157	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
158	     */
159	    private static String normalizeEmail(String email) {
160	        if (email == null || email.isBlank()) {
161	            return null;
162	        }
163	        String trimmed = email.trim();
164	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
165	            throw new InvalidEmailException("Email must be a syntactically valid address");
166	        }
167	        return trimmed.toLowerCase(Locale.ROOT);
168	    }
169	
170	    /**
171	     * Rejects a create whose normalized telephone is already used by any existing owner, so that
172	     * telephones stay unique across owners. Telephones are normalized to their 10-digit form on
173	     * create, so a direct equality comparison against the stored values is sufficient.
174	     *
175	     * @param normalizedTelephone the normalized 10-digit telephone of the owner being created
176	     * @throws DuplicateTelephoneException if another owner already uses this telephone
177	     */
